package com.mycompany.rentalmanagement.dao;
import com.mycompany.rentalmanagement.DBConnection;import java.sql.*;import java.math.*;import java.util.*;
public class PaymentDAO {
 public List<Map<String,Object>> list()throws SQLException{List<Map<String,Object>> a=new ArrayList<>();String sql="SELECT p.*,r.status rental_status,c.full_name customer_name,v.registration_number FROM payments p JOIN rentals r ON r.id=p.rental_id JOIN customers c ON c.id=r.customer_id JOIN vehicles v ON v.id=r.vehicle_id ORDER BY p.id DESC";try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(String k:new String[]{"id","rental_id","amount","payment_method","reference_number","notes","paid_at","customer_name","registration_number"})m.put(k,r.getObject(k));a.add(m);}}return a;}
 public List<Map<String,Object>> payableRentals()throws SQLException{List<Map<String,Object>> a=new ArrayList<>();String sql="SELECT r.id,CONCAT('#',r.id,' • ',c.full_name,' • ',v.registration_number,' • due ₹',GREATEST(COALESCE(r.final_total,r.estimated_total)-COALESCE(SUM(p.amount),0),0)) label FROM rentals r JOIN customers c ON c.id=r.customer_id JOIN vehicles v ON v.id=r.vehicle_id LEFT JOIN payments p ON p.rental_id=r.id WHERE r.status IN ('BOOKED','ACTIVE','COMPLETED') GROUP BY r.id,c.full_name,v.registration_number,r.final_total,r.estimated_total HAVING GREATEST(COALESCE(r.final_total,r.estimated_total)-COALESCE(SUM(p.amount),0),0)>0 ORDER BY r.id DESC";try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){while(r.next()){Map<String,Object> m=new HashMap<>();m.put("id",r.getLong(1));m.put("label",r.getString(2));a.add(m);}}return a;}
 public void record(long rental,BigDecimal amount,String method,String ref,String notes)throws Exception{if(amount.signum()<=0)throw new IllegalArgumentException("Payment must be greater than zero.");try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{BigDecimal total;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(final_total,estimated_total) FROM rentals WHERE id=? FOR UPDATE")){p.setLong(1,rental);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Rental not found.");total=r.getBigDecimal(1);}}BigDecimal paid;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(SUM(amount),0) FROM payments WHERE rental_id=?")){p.setLong(1,rental);try(ResultSet r=p.executeQuery()){r.next();paid=r.getBigDecimal(1);}}if(amount.compareTo(total.subtract(paid))>0)throw new IllegalArgumentException("Payment exceeds outstanding balance of ₹"+total.subtract(paid).max(BigDecimal.ZERO));try(PreparedStatement p=c.prepareStatement("INSERT INTO payments(rental_id,amount,payment_method,reference_number,notes) VALUES(?,?,?,?,?)")){p.setLong(1,rental);p.setBigDecimal(2,amount);p.setString(3,method);p.setString(4,ref);p.setString(5,notes);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
}
